		var c0: int = floor_div(rx0[r], CELL); var c1: int = floor_div(rx1[r] - 1, CELL)
		var d0: int = floor_div(ry0[r], CELL); var d1: int = floor_div(ry1[r] - 1, CELL)
		for cy in range(d0, d1 + 1):
			for cx in range(c0, c1 + 1):
				counts[cy * gw + cx] += 1
