		var t2: int = Time.get_ticks_usec()
		var sum3: int = 0
		for i in iters:
			sum3 += q_brute(xs[i], ys[i], xs[i] + w, ys[i] + h, 3, o3)
		var t3: int = Time.get_ticks_usec()
		var empt: int = 0
		for i in iters:
			empt += xs[i]
		var t4: int = Time.get_ticks_usec()
		print("box ", w, "x", h, " iters ", iters, " avg results ", float(sum1) / iters)
		print("  markfind  us/query ", float(t1 - t0) / iters, "  MEMORY_STATIC delta ", m2 - m1)
		print("  stamp+ins us/query ", float(t2 - t1) / iters)
		print("  brute     us/query ", float(t3 - t2) / iters, "  (loop overhead ", float(t4 - t3) / iters, ")")
	# floor_div cost
	var t5: int = Time.get_ticks_usec()
	var s: int = 0
	for i in 100000:
		s += floor_div(i - 500, 48)
	var t6: int = Time.get_ticks_usec()
	print("floor_div us/call ", float(t6 - t5) / 100000.0)
	# find cost full-scan 2000 bytes
	var z := PackedByteArray(); z.resize(2000); z.fill(0); z[1999] = 1
	var t7: int = Time.get_ticks_usec()
	var q: int = 0
	for i in 20000:
		q += z.find(1, 0)
	var t8: int = Time.get_ticks_usec()
	print("find 2000-byte scan us/call ", float(t8 - t7) / 20000.0)
	quit()
