						n += 1
	for k in n:
		var r: int = cand[k]
		if k >= out.keys.size(): out.grow()
		out.keys[k] = rkey[r]
		var s: int = k * 4
		out.spans[s] = rx0[r]; out.spans[s + 1] = ry0[r]; out.spans[s + 2] = rx1[r] - 1; out.spans[s + 3] = ry1[r] - 1
		out.flags[k] = rflags[r]
	out.count = n
	return n

func q_brute(a0: int, b0: int, a1: int, b1: int, mask: int, out: Buf) -> int:
	out.count = 0
	var cnt: int = 0
	if a1 <= a0 or b1 <= b0:
		return 0
	for r in N:
		if (rflags[r] & mask) != 0 and rx0[r] < a1 and a0 < rx1[r] and ry0[r] < b1 and b0 < ry1[r]:
			if cnt >= out.keys.size(): out.grow()
			out.keys[cnt] = rkey[r]
			var s: int = cnt * 4
			out.spans[s] = rx0[r]; out.spans[s + 1] = ry0[r]; out.spans[s + 2] = rx1[r] - 1; out.spans[s + 3] = ry1[r] - 1
			out.flags[cnt] = rflags[r]
			cnt += 1
	out.count = cnt
	return cnt

func same(a: Buf, b: Buf) -> bool:
	if a.count != b.count: return false
	for i in a.count:
		if a.keys[i] != b.keys[i]: return false
		if a.flags[i] != b.flags[i]: return false
		for j in 4:
			if a.spans[i * 4 + j] != b.spans[i * 4 + j]: return false
	return true

